
Component({
  data: {
    selected: 0,
    list: [] as any[]
  },
  lifetimes: {
    attached() {
      this.updateTabs()
    }
  },
  methods: {
    updateTabs() {
      const list = [
        {
          pagePath: "/pages/index/index",
          text: "记录",
          iconPath: "data:image/svg+xml;base64,",
          selectedIconPath: "data:image/svg+xml;base64,"
        },
        {
          pagePath: "/pages/todo/todo",
          text: "待办",
          iconPath: "data:image/svg+xml;base64,",
          selectedIconPath: "data:image/svg+xml;base64,"
        },
        {
          pagePath: "/pages/records/records",
          text: "历史",
          iconPath: "data:image/svg+xml;base64,",
          selectedIconPath: "data:image/svg+xml;base64,"
        },
        {
          pagePath: "/pages/stats/stats",
          text: "我的",
          iconPath: "data:image/svg+xml;base64,",
          selectedIconPath: "data:image/svg+xml;base64,"
        }
      ]
      this.setData({ list })
    },
    switchTab(e: any) {
      const data = e.currentTarget.dataset
      const url = data.path
      wx.switchTab({ url })
    }
  }
})

